    bg = max(set(v for row in grid for v in row),
             key=lambda v: sum(row.count(v) for row in grid))

    # Look for full, uniform divider rows or columns.
    for axis in (0, 1):
        n = h if axis == 0 else w
        m = w if axis == 0 else h
        lines = []
        for i in range(n):
            vals = [grid[i][j] if axis == 0 else grid[j][i] for j in range(m)]
            if len(set(vals)) == 1 and vals[0] != bg:
                lines.append((i, vals[0]))

        if not lines:
            continue

        # Repeated dividers define a repeating tile, including the divider.
        if len(lines) >= 2:
            step = lines[1][0] - lines[0][0]
            if step <= 0:
