def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter

    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    rows, cols = [], []

    for r in range(h):
        if grid[r][0] != bg and all(v == grid[r][0] for v in grid[r]):
            rows.append(r)
    for c in range(w):
        if grid[0][c] != bg and all(grid[r][c] == grid[0][c] for r in range(h)):
            cols.append(c)

    def segments(size, separators):
        result, start = [], 0
        for p in separators:
            if start < p:
                result.append((start, p))
            start = p + 1
        if start < size:
            result.append((start, size))
        return result

    row_blocks = segments(h, rows)
    col_blocks = segments(w, cols)
    if not row_blocks or not col_blocks:
        return grid

    # The tile containing the most non-background cells is the pattern tile.
    source = max(
        ((rb, cb) for rb in row_blocks for cb in col_blocks),
        key=lambda pair: sum(
            grid[r][c] != bg
            for r in range(pair[0][0], pair[0][1])
            for c in range(pair[1][0], pair[1][1])
        )
    )
    sr, sc = source
    tile = [row[sc[0]:sc[1]] for row in grid[sr[0]:sr[1]]]
    out = [row[:] for row in grid]

    for rb in row_blocks:
        for cb in col_blocks:
            for r in range(rb[0], rb[1]):
                for c in range(cb[0], cb[1]):
                    tr = (r - rb[0]) % len(tile)
                    tc = (c - cb[0]) % len(tile[0])
                    out[r][c] = tile[tr][tc]

    return out
